// Fast RLE Draw Functions
inline void draw_rle_sprite(std::uint32_t* fb, int fb_w, int fb_h, const RleSprite& sprite, int dx, int dy, int scale = 1, bool transparent_zero = true) {
    int cur_x = 0;
    int cur_y = 0;
    for (int i = 0; i < sprite.rle_size; ++i) {
        std::uint8_t b = sprite.data[i];
        int run = ((b >> 4) & 0x0F) + 1;
        int col_idx = b & 0x0F;
        std::uint32_t color = PALETTE_DANCHEONG_16[col_idx];

        for (int r = 0; r < run; ++r) {
            if (!transparent_zero || col_idx != 0) {
                for (int sy = 0; sy < scale; ++sy) {
                    int py = dy + cur_y * scale + sy;
                    if (py < 0 || py >= fb_h) continue;
                    for (int sx = 0; sx < scale; ++sx) {
                        int px = dx + cur_x * scale + sx;
                        if (px < 0 || px >= fb_w) continue;
                        fb[py * fb_w + px] = color;
                    } // sx
                } // sy
            } // not transparent
            cur_x++;
            if (cur_x >= sprite.width) {
                cur_x = 0;
                cur_y++;
                if (cur_y >= sprite.height) break;
            }
        } // r
    } // i
}

inline void draw_rle_tile(std::uint32_t* fb, int fb_w, int fb_h, const RleSprite& tile, int dx, int dy) {
    draw_rle_sprite(fb, fb_w, fb_h, tile, dx, dy, 1, false);
}

